"""
	Function for word preprocessing
	|
	| Argument
	| | word: a string to be processed
	|
	| Parameter
	| | ignore_non_alnumspc: whether to remove all non alpha/numeric/space characters
	| | ignore_space: whether to remove all spaces
	| | ignore_numeric: whether to remove all numeric characters
	| | ignore_case: whether to convert all alpha characters to lower case
	|
	| Output
	| | processed string (type: str)
	"""
def word_preprocessing(
    word: Any,
    ignore_non_alnumspc: Any = True,
    ignore_space: Any = True,
    ignore_numeric: Any = True,
    ignore_case: Any = True
) -> object {
    if ignore_non_alnumspc {
        word = "".join(filter(lambda (x: Any) { (x.isalnum() or x.isspace()); }, word));
    }
    if ignore_space {
        word = "".join(filter(lambda (x: Any) { not x.isspace(); }, word));
    }
    if ignore_numeric {
        word = "".join(filter(lambda (x: Any) { not x.isnumeric(); }, word));
    }
    if ignore_case {
        word = word.lower();
    }
    return word;
}

